definition.script:
// Configuration
var token = input.get("accessToken");
var groupId = input.get("groupId");
var maxPages = parseInt(input.get("maxPages")) || 100;
var pageSize = parseInt(input.get("pageSize")) || 100;
var selectFields = input.get("selectFields") || "";

// Validate inputs
if (!token) {
    log.error("Access token is required");
    output.set("HasErrors", true);
    output.set("ErrorMessage", "Access token is required");
    tags.trigger("error");
} else if (!groupId) {
    log.error("Group ID is required");
    output.set("HasErrors", true);
    output.set("ErrorMessage", "Group ID is required");
    tags.trigger("error");
} else {
    // Initialize
    var allMembers = [];
    var pagesProcessed = 0;
    var hasErrors = false;
    var errorMessage = "";

    // Build initial URL
    var nextUrl = "https://graph.microsoft.com/v1.0/groups/" + encodeURIComponent(groupId) + "/members?$top=" + pageSize;
    if (selectFields) {
        nextUrl += "&$select=" + selectFields;
    }

    // Headers for Graph API
    var headers = {
        "Authorization": "Bearer " + token,
        "Accept": "application/json",
        "ConsistencyLevel": "eventual"
    };

    log.info("Fetching members for group: " + groupId + ", max pages: " + maxPages);

    // Pagination loop
    while (nextUrl && pagesProcessed < maxPages) {
        pagesProcessed++;
        log.debug("Fetching page " + pagesProcessed + ": " + nextUrl);

        try {
            var response = http.get(nextUrl, headers);

            if (response.statusCode === 404) {
                hasErrors = true;
                errorMessage = "Group not found: " + groupId;
                log.error(errorMessage);
                break;
            } else if (!response.isSuccess) {
                hasErrors = true;
                errorMessage = "API error on page " + pagesProcessed + ": HTTP " + response.statusCode;
                log.error(errorMessage);
                break;
            }

            var data = json.parse(response.body);

            // Extract members from response
            if (data && data.value && Array.isArray(data.value)) {
                for (var i = 0; i < data.value.length; i++) {
                    allMembers.push(data.value[i]);
                }
                log.info("Page " + pagesProcessed + ": Retrieved " + data.value.length + " members");
            }

            // Check for next page (OData uses @odata.nextLink)
            if (data && data["@odata.nextLink"]) {
                nextUrl = data["@odata.nextLink"];
            } else {
                nextUrl = null;
            }

        } catch (ex) {
            hasErrors = true;
            errorMessage = "Exception on page " + pagesProcessed + ": " + ex.message;
            log.error(errorMessage);
            break;
        }
    }

    // Count member types
    var userCount = 0;
    var groupCount = 0;
    var otherCount = 0;
    for (var j = 0; j < allMembers.length; j++) {
        var memberType = allMembers[j]["@odata.type"] || "";
        if (memberType.indexOf("user") > -1) {
            userCount++;
        } else if (memberType.indexOf("group") > -1) {
            groupCount++;
        } else {
            otherCount++;
        }
    }

    // Set outputs
    output.set("Members", allMembers);
    output.setJson("MembersJson", allMembers);
    output.set("TotalCount", allMembers.length);
    output.set("UserCount", userCount);
    output.set("GroupCount", groupCount);
    output.set("OtherCount", otherCount);
    output.set("PagesProcessed", pagesProcessed);
    output.set("HasErrors", hasErrors);
    output.set("ErrorMessage", errorMessage);

    log.info("Completed: " + allMembers.length + " members (" + userCount + " users, " + groupCount + " groups) in " + pagesProcessed + " pages");

    // Trigger appropriate connection tag
    if (hasErrors) {
        tags.trigger("error");
    } else if (allMembers.length === 0) {
        tags.trigger("empty");
    } else {
        tags.trigger("success");
    }
}
